from datetime import date
from decimal import Decimal


class Loyalty:
    def __init__(self) -> None:
        self._purchases: dict[str, list[tuple[date, int]]] = {}
        self._redemptions: dict[str, list[tuple[date, int]]] = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")

        points = int(Decimal(str(amount)) // 10)
        self._purchases.setdefault(customer, []).append((day, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        earned = sum(
            points
            for purchase_day, points in self._purchases.get(customer, [])
            if (day - purchase_day).days >= 14
        )
        redeemed = sum(
            points
            for redemption_day, points in self._redemptions.get(customer, [])
            if redemption_day <= day
        )
        return earned - redeemed

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points < 0 or points % 100 != 0:
            raise ValueError("Redemption must be a nonnegative multiple of 100")
        if points > self.balance(customer, day):
            raise ValueError("Insufficient available points")

        self._redemptions.setdefault(customer, []).append((day, points))
```

